ate\",\n                  \"allowFutureDates\": false\n                }\n              ]\n            },\n            {\n              \"type\": \"obs\",\n              \"historicalExpression\": \"HD.getObject(\'prevEnc\').getValue(\'8002f0e5-43eb-4aa8-96dd-2120325f6095\')\",\n              \"questionOptions\": {\n                \"rendering\": \"date\",\n                \"concept\": \"8002f0e5-43eb-4aa8-96dd-2120325f6095\",\n                \"calculate\": {\n                  \"calculateExpression\": \"calcEDD(lastMenstrualPeriod)\"\n                }\n              },\n              \"id\": \"expectedDateOfDelivery\",\n              \"label\": \"Expected Date of Delivery (EDD)\",\n              \"datePickerFormat\": \"calendar\",\n              \"questionInfo\": \"EDD is LMP + 9months 7 days\",\n              \"readonly\": true\n            },\n            {\n              \"type\": \"obs\",\n              \"historicalExpression\": \"HD.getObject(\'prevEnc\').getValue(\'4dd1c561-ae28-4c33-9791-d6734517efab\')\",\n              \"questionOptions\": {\n                \"rendering\": \"select\",\n                \"concept\": \"4dd1c561-ae28-4c33-9791-d6734517efab\",\n                \"answers\": [\n                  {\n                    \"concept\": \"47dd12f2-f0f4-4302-898e-bb8023ff812e\",\n                    \"label\": \"1st TD\"\n                  },\n                  {\n                    \"concept\": \"06a6ffa1-9444-4ee8-8c6c-d72c835fd44f\",\n                    \"label\": \"2nd TD\"\n                  },\n                  {\n                    \"concept\": \"8443dd77-bb36-4a5e-b536-8d04851498d6\",\n                    \"label\": \"2+ TD\"\n                  }\n                ]\n              },\n              \"id\": \"tdGiven\",\n              \"label\": \"TD given\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"066ec5d8-