ansfusionProvided) || (bloodTransfusionProvided !== \'1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')\"\n              }\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Diagnosis\",\n      \"sections\": [\n        {\n          \"label\": \"Diagnosis & Risk Assessment\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"checkbox\",\n                \"concept\": \"29f3565a-b844-4562-a1e7-b374d0098401\",\n                \"answers\": [\n                  {\n                    \"concept\": \"121812AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Acute hepatitis B\"\n                  },\n                  {\n                    \"concept\": \"94b2ba33-0e99-4d34-92d8-9aa051f3a194\",\n                    \"label\": \"Analcephaly\"\n                  },\n                  {\n                    \"concept\": \"121629AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Anemia\"\n                  },\n                  {\n                    \"concept\": \"7d594f73-45ce-49fe-8aa2-b2bb693db694\",\n                    \"label\": \"Chronic hypertension in pregnancy\"\n                  },\n                  {\n                    \"concept\": \"1449AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Gestational Diabetes\"\n                  },\n                  {\n                    \"concept\": \"28AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Hepatitis C\"\n                  },\n                  {\n                    \"concept\": \"138571AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"HIV positive\"\n                  },\n                  {\n                    \"concept\": \"b665d3fb-d0aa-4a3e-ad2e-125b5878e20f\",\n                    \"label\": \"New onset hypertension in pregnancy\"\n                  },\n      