ering\": \"radio\",\n                \"concept\": \"aeff1ac5-67a9-4ce6-89c0-3692835f241e\",\n                \"answers\": [\n                  {\n                    \"concept\": \"f4d3c9bb-b39a-4f12-9154-270ed2018b0e\",\n                    \"label\": \"Slowly\"\n                  },\n                  {\n                    \"concept\": \"c557490d-5d52-4717-a608-e54b464cb439\",\n                    \"label\": \"Very Slowly\"\n                  }\n                ]\n              },\n              \"id\": \"skinPinch\",\n              \"label\": \"Skin pinch\",\n              \"hide\": {\n                \"hideWhenExpression\": \"isEmpty(dehydrationStatus) || (dehydrationStatus == \'1175AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \" Low weight/ Feeding Problem\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"9cf32a21-631e-4f8c-8d53-4db6b3ad46dc\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  },\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  }\n                ]\n              },\n              \"id\": \"breastfeed\",\n              \"label\": \"Breast Feed\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"5870aac0-15b1-4b4c-8cc4-7b88c6967910\"\n              },\n              \"id\": \"breastFeeding,HowManyTimesIn24Hours?\",\n              \"label\": \"Breast feeding, How many times in 24 hours?\",\n              \"hide\": {\n    