INSERT INTO `concept_description` VALUES
(1,3,'A convenience set for billable services','en',2,'2026-06-09 06:49:36',NULL,NULL,'abf1c018-f18a-5371-8ad4-8596ecc8327f'),
(2,4,'A species of parasitic nematode that is the largest found in the human intestine. Its distribution is worldwide, but it is more prevalent in areas of poor sanitation. Human infection with A. lumbricoides is acquired by swallowing fully embryonated eggs from contaminated soil.','en',2,'2026-06-09 06:49:36',NULL,NULL,'11475FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(3,5,'Infection with any of various amebae. It is an asymptomatic carrier state in most individuals, but diseases ranging from chronic, mild diarrhea to fulminant dysentery may occur.','en',2,'2026-06-09 06:49:36',NULL,NULL,'11388FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(5,8,'A species of trematode blood flukes of the family Schistosomatidae. It is common in the Nile delta. The intermediate host is the planorbid snail. This parasite causes schistosomiasis mansoni and intestinal bilharziasis.','en',2,'2026-06-09 06:49:36',NULL,NULL,'8165FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(8,11,'Peripheral smear study for malarial parasites is the gold standard in diagnosing malarial infection. It involves collection of a blood smear, staining and examination of the the red blood cells for intracellular malarial parasites.','en',2,'2026-06-09 06:49:36',NULL,NULL,'33FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(9,12,'Evaluation of stool under a microscope, usually for ova and parasites.','en',2,'2026-06-09 06:49:37',NULL,NULL,'305FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(11,14,'A subclass of segmented worms comprising the tapeworms.','en',2,'2026-06-09 06:49:37',NULL,NULL,'6159FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(12,16,'Descriptive term: not precisely defined, determinable, or established.','en',2,'2026-06-09 06:49:37',NULL,NULL,'1141FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(16,21,'A genus of nematode intestinal parasites that consists of several species. A. duodenale is the common hookworm in humans. A. braziliense, A. ceylonicum, and A. caninum occur primarily in cats and dogs, but all have been known to occur in humans.','en',2,'2026-06-09 06:49:37',NULL,NULL,'15166FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(17,22,'An intentional relinquishment of some rights for example the claim of a bill against the cost of a service or commodity','en',2,'2026-06-09 06:49:37',NULL,NULL,'980FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(18,24,'none','en',2,'2026-06-09 06:49:37',NULL,NULL,'2115FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(19,25,'none','en',2,'2026-06-09 06:49:38',NULL,NULL,'2112FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(20,26,'Subscriber type for insurance coverage documentation','en',2,'2026-06-09 06:49:38',NULL,NULL,'15972FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(21,27,'A pharmacy, drug store or other location to obtain medicines.','en',2,'2026-06-09 06:49:38',NULL,NULL,'1577FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(22,28,'Method of payment, coverage for health related expenses','en',2,'2026-06-09 06:49:38',NULL,NULL,'313b95ba-2e76-449d-855b-9662ea49b64d'),
(23,29,'A form of payment using mobile phones linked to bank accounts.','en',2,'2026-06-09 06:49:38',NULL,NULL,'703d7e5e-9169-4cc5-a46e-1370bf1b59e6'),
(24,30,'Credit card form of payment','en',2,'2026-06-09 06:49:38',NULL,NULL,'a379584d-139c-496e-9376-f2ab6509972c'),
(25,31,'Currency as form of payment','en',2,'2026-06-09 06:49:38',NULL,NULL,'2c838d7f-59e5-4b5e-ad7a-9cc3461e9227'),
(26,33,'The euro is the official currency of 20 of the 27 member states of the European Union','en',2,'2026-06-09 06:49:38',NULL,NULL,'38796e84-3836-4744-a527-2c2fe1f9e0f8'),
(27,34,'The shilling is the currency of Uganda','en',2,'2026-06-09 06:49:38',NULL,NULL,'365ace25-399f-4507-8a1d-f41bfa8851a5'),
(28,35,'The shilling (Swahili: shilingi; abbreviation: TSh; code: TZS) is the currency of Tanzania. It is subdivided into 100 cents.','en',2,'2026-06-09 06:49:38',NULL,NULL,'585cfec5-4a26-448d-a977-5c127b4f10b9'),
(29,36,'The naira is the currency of Nigeria. One naira is divided into 100 kobo.','en',2,'2026-06-09 06:49:38',NULL,NULL,'b95e7004-ff57-45a7-bd8c-ca2a9e245752'),
