INSERT INTO `global_property` VALUES
('@openmrs/esm-fast-data-entry-app.groupSessionVisitTypeUuid','78370d15-38ad-48a1-825f-f0e9ff60d5a1','UUID of the visit type used by Fast Data Entry to create visits when in \'group sessions\' entry workflow','71834142-c3f8-4a45-ac0f-ae991d210239',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.addressToEntryMapUpdaterLastStartTime',NULL,'The module uses this field to store when the AddressToEntryMapUpdater task was last started; DO NOT MODIFY','62e8ec57-45e7-4607-8925-6dfdb36000e7',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.allowFreetext','true','Valid values: true/false. When overriding the address portlet, allow the entry of free text for address fields associated with the address hierarchy by providing an \"Other\" option','1d04c144-25ae-4f65-bc88-cfea5e57559c',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.enableOverrideOfAddressPortlet','true','Valid values: true/false. When enabled, the existing \"edit\" component of the address portlet is overridden by the new functionality provided by the address hierarchy module','a4cd7687-f0ac-4fb5-a06f-16418f43c5e9',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.initializeAddressHierarchyCacheOnStartup','true','Sets whether to initialize the address hierarchy in-memory cache (which is used to speed up address hierarchy searches.\nGenerally, you want to set this to \"true\", though developers may want to set it to false during development\nto speed module start-up.','3415118d-85ac-4330-95e4-fa9d5bfd60c3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.mandatory','false','true/false whether or not the addresshierarchy module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','8e7d998b-e8bf-4630-a538-3ebce2bf918c',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.soundexProcessor',NULL,'If the Name Phonetics module is installed, this defines the name of a soundex algorithm used by the getPossibleFullAddresses service method.','643228b4-a10c-431c-8a6c-730889ea64ca',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.started','true','DO NOT MODIFY. true/false whether or not the addresshierarchy module has been started.  This is used to make sure modules that were running  prior to a restart are started again','27bfa638-2554-44fe-ba70-6bfc35534565',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.allergen.ConceptClasses','Drug,MedSet','A comma-separated list of the allowed concept classes for the allergen field of the allergy dialog','eaf3f161-3752-412e-9a88-7bba5b702345',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.allergen.drug','162552AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the drug allergens concept','73901ac7-58af-4af7-ba24-84d4fa6cc5b9',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.allergen.environment','162554AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the environment allergens concept','11df86f4-9ac9-4ef0-9c27-794b6e80ac30',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.allergen.food','162553AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the food allergens concept','7a5d3497-9451-43e3-9875-577401e7e3e8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.otherNonCoded','5622AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the allergy other non coded concept','e58daa38-3811-44b1-b46e-576c33ef15c0',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.reactions','162555AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the allergy reactions concept','b31775b0-c9f7-4182-b5b3-8215057d0c36',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.severity.mild','1498AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the MILD severity concept','9cfc01ef-aed3-429f-afd7-5f5a85c1a8ee',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.severity.moderate','1499AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the MODERATE severity concept','48acac7b-3eb4-4aff-ae1b-19ce279ca7b6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.severity.severe','1500AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the SEVERE severity concept','4fa87d11-8875-49d1-87d2-2750397670af',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.unknown','1067AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the allergy unknown concept','7e0827a8-d31b-4977-9b9a-fd8c2e2725f2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.reaction.ConceptClasses','Symptom','A comma-separated list of the allowed concept classes for the reaction field of the allergy dialog','5362e179-b305-4f3d-a689-1171cfcd5cbc',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('application.name','OpenMRS','The name of this application, as presented to the user, for example on the login and welcome pages.','e7681fbd-f513-40a2-bfdc-0c81c43842f4',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('appointments.mandatory','false','true/false whether or not the appointments module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','106c0f10-8659-4c91-a8b9-79ebcf14f6a7',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('appointments.started','true','DO NOT MODIFY. true/false whether or not the appointments module has been started.  This is used to make sure modules that were running  prior to a restart are started again','6ef9c952-4bcd-4b64-8939-234c9964cebe',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForAppointments','/openmrs/ws/rest/v1/appointments/{uuid}','URL pattern to use for published appointment events. Default is /openmrs/ws/rest/v1/appointments/{uuid}. If you change default value, please add your custom implementation for the given URL','54bbed8c-63cf-11f1-83b0-2ae072fd45a6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForAppointmentService','/openmrs/ws/rest/v1/appointment-services/{uuid}','URL pattern to use for published appointment service events. Default is /openmrs/ws/rest/v1/appointment-services/{uuid}. If you change default value, please add your custom implementation for the given URL','54ba1902-63cf-11f1-83b0-2ae072fd45a6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForBedTagMap','/openmrs/ws/rest/v1/bedTagMap/{uuid}','URL pattern to use for published bed tag map events. Default is /openmrs/ws/rest/v1/bedTagMap/{uuid}. If you change default value, please add your custom implementation for the given URL.','52102812-63cf-11f1-83b0-2ae072fd45a6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForRecurringAppointments','/openmrs/ws/rest/v1/recurring-appointments?uuid={uuid}','URL pattern to use for published Recurring appointment events. Default is /openmrs/ws/rest/v1/recurring-appointments?uuid={uuid}. If you change default value, please add your custom implementation for the given URL','54d1b803-63cf-11f1-83b0-2ae072fd45a6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForAppointments','true','If set true, events related to appointment changes are published','54bb0f43-63cf-11f1-83b0-2ae072fd45a6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForAppointmentService','true','If set true, events related to appointment service changes are published','54b8e9a2-63cf-11f1-83b0-2ae072fd45a6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForBedTagMapChange','true','If set true, events related to bed tag map changes are published','520f57c0-63cf-11f1-83b0-2ae072fd45a6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.allowedFileExtensions','jpeg,jpg,png,pdf',NULL,'a6c552db-1a2c-4274-9424-97e3a8f68ae9',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
