INSERT INTO `serialized_object` VALUES
(1,'Patient Identifier Sticker','','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.report.definition.ReportDefinition id=\"1\" uuid=\"08e2d4eb-91f7-4067-a0c9-025af2122686\" retired=\"false\">\n  <name>Patient Identifier Sticker</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"A4F30A1B-5EB9-11DF-A648-37A07F9C90FB\"/>\n  <dateCreated id=\"3\">2026-06-09 07:36:17 UTC</dateCreated>\n  <parameters id=\"4\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"5\">\n      <name>patientUuid</name>\n      <label>Patient UUID</label>\n      <type>java.lang.String</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <dataSetDefinitions class=\"linked-hash-map\" id=\"6\">\n    <entry>\n      <string>fields</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"7\">\n        <parameterizable class=\"org.openmrs.module.patientdocuments.library.PatientIdStickerDataSetDefinition\" id=\"8\" retired=\"false\">\n          <parameters reference=\"4\"/>\n        </parameterizable>\n        <parameterMappings id=\"9\">\n          <entry>\n            <string>patientUuid</string>\n            <string>${patientUuid}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n  </dataSetDefinitions>\n</org.openmrs.module.reporting.report.definition.ReportDefinition>','2026-06-09 07:36:17',2,NULL,NULL,0,NULL,NULL,NULL,'08e2d4eb-91f7-4067-a0c9-025af2122686');
